def grundy(g):
	if g in gdic:
		return gdic[g]
	lg = len(g)
	subg = set()
	for (ln, w) in words:
		pos = g.find(w)
		while pos >= 0:
			gpre = grundy(g[:pos])
			gpost = grundy(g[pos + ln:])
			subg.add(gpre ^ gpost)
			pos = g.find(w, pos + 1)
	if len(subg) == 0:
		gdic[g] = 0
	else:
		mex = 0
		while mex in subg:
			mex += 1
		gdic[g] = mex
	return gdic[g]
for _ in range(int(input())):
	game = input().strip()
	n = int(input())
	wordset = set((input().strip() for _ in range(n)))
	words = [(len(w), w) for w in wordset]
	gdic = {'': 0}
	print('Teddy' if grundy(game) > 0 else 'Tracy')
